 function play(k,beat){var b=bufs[k];if(!b)return;var s=ctx.createBufferSource(),pg=G(0),st=beat-PRE,now=ctx.currentTime,off=Math.max(0,now-st);
  s.buffer=b;chain(s,pg,vIn);pg.gain.setValueAtTime(0,st+off);pg.gain.linearRampToValueAtTime(k==='neon'?1.26:1,st+off+0.015);s.start(st+off,off)}
