 var tape=ctx.createWaveShaper();tape.curve=curve(1.4);tape.oversample='2x';
 var hp=F('highpass',36,0.7),lows=F('lowshelf',75),pres=F('peaking',1400,0.8),highs=F('highshelf',6500);
