 dL.delayTime.value=ST*3;dR.delayTime.value=ST*3;
 chain(dIn,dLP,dL,dR,fb,dLP);dL.connect(mg,0,0);dR.connect(mg,0,1);mg.connect(dOut);dOut.connect(bus);dOut.connect(hallIn);
 /* buses */
 var bassIn=G(1.8),bassSh=ctx.createWaveShaper();bassSh.curve=curve(S.drive);bassSh.oversample='4x';
 var bassBus=G(S.bassLvl*0.3);var bp=F('peaking',800,0.8);bp.gain.value=5;
